from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, write_time = cache[key]
        return t >= write_time + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # purge expired entries lazily is optional, but let's clean expired current key
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]  # will re-insert, remove to update position

            if key not in cache:
                # need to check capacity, but first remove any expired entries to make room properly?
                # Eviction only considers actual present (non-expired) entries.
                if len(cache) >= capacity:
                    # evict least recently used entries until space available,
                    # but skip/remove expired ones during search (they don't count anyway)
                    evict_key = None
                    for k in list(cache.keys()):
                        if is_expired(k, t):
                            del cache[k]
                        else:
                            evict_key = k
                            break
                    if len(cache) >= capacity:
                        # evict LRU (first item)
                        if cache:
                            oldest_key = next(iter(cache))
                            del cache[oldest_key]

            cache[key] = (value, t)
            cache.move_to_end(key)

        else:  # get
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, write_time = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

